const BOOK_PAGES = [{"type": "cover", "page_num": 1, "title": "Front Cover", "html": "\n    <div class=\"page-cover\">\n        <div class=\"cover-badge\">COMPREHENSIVE MASTERCLASS</div>\n        <h1 class=\"cover-title\">120 RULES<br><span class=\"accent-text\">OF GRAMMAR</span></h1>\n        <p class=\"cover-subtitle\">Complete 3D Digital Edition & Quick Recall Handbook</p>\n        <div class=\"cover-divider\"></div>\n        <p class=\"cover-author\">Based on the Curriculum by <strong>Nimisha Bansal</strong></p>\n        <div class=\"cover-tags\">\n            <span>Bank PO & Clerk</span>\n            <span>SSC CGL & CHSL</span>\n            <span>CDS & NDA</span>\n            <span>Error Detection</span>\n        </div>\n        <div class=\"cover-footer\">\n            <span class=\"cover-hint\">Click next arrow or swipe to open book</span>\n        </div>\n    </div>\n    "}, {"type": "cheat1", "page_num": 2, "title": "Quick Recall: Rules 1\u201315", "html": "<div class='page-content'><div class='page-header-title'>\u26a1 Executive Quick Recall Sheet (1\u201315)</div><p class='page-sub'>Key rules for 5-minute revision before exams.</p><div class='cheat-grid'>\n    <div class='cheat-item'>\n        <div class='cheat-title'>Each / Every / Neither of</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Singular Noun + <b>Singular Verb</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Do not use plural verb (*'Each of them are'*).</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Neither... nor / Either... or</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Verb matches <b>closest subject</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Matching the first subject instead of closest.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>As well as / Along with</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Verb matches <b>first subject</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Getting distracted by the plural noun inside commas.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Both ... and</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Always positive; <b>NEVER use 'not' with 'both'</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Replace 'both not' with 'neither... nor'.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>A number of vs The number of</div>\n        <div class='cheat-rule'><strong>Rule:</strong> <b>A number = Plural Verb</b>; <b>The number = Singular Verb</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Flipping singular/plural rules.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>One of the + Plural Noun</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Takes <b>Singular Verb</b> (unless 'who/that' follows)</div>\n        <div class='cheat-trap'><strong>Trap:</strong> If 'who/that' follows, verb is <b>Plural</b> (unless 'the only').</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Many a / an</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Singular Noun + <b>Singular Verb</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Using plural noun or verb (*'Many a boys are'*).</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Hardly / Scarcely</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Inversion + paired strictly with <b>WHEN</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Never pair with 'than' or 'then'.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>No sooner</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Inversion + paired strictly with <b>THAN</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Never pair with 'when' or 'then'.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Senior / Junior / Superior</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Followed by <b>TO</b> (never 'than')</div>\n        <div class='cheat-trap'><strong>Trap:</strong> Never add 'more' or use 'than'.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Prefer / Preferable</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Followed by <b>TO</b> (never 'than')</div>\n        <div class='cheat-trap'><strong>Trap:</strong> Never say 'more preferable than'.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Lest</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Paired with <b>SHOULD</b>; <b>NO 'not'</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Never use 'will', 'may', or negative words.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Unless vs Until</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Unless = Condition; Until = Time. <b>NO 'not' in clause</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Never use double negatives or future tense.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>It is high time + Subject</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Strictly takes <b>Simple Past (V2)</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Never use present tense (*'It is high time we go'*).</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Had better / Would rather</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Followed by <b>Bare Infinitive (V1)</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Never add 'to' (*'had better to go'*).</div>\n    </div>\n    </div></div>"}, {"type": "cheat2", "page_num": 3, "title": "Quick Recall: Rules 16\u201330", "html": "<div class='page-content'><div class='page-header-title'>\u26a1 Executive Quick Recall Sheet (16\u201330)</div><p class='page-sub'>Key rules for 5-minute revision before exams.</p><div class='cheat-grid'>\n    <div class='cheat-item'>\n        <div class='cheat-title'>Looking forward to / Accustomed to</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Followed by <b>Gerund (V1 + ing)</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Confusing preposition 'to' with infinitive particle.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Unreal Conditional (If I were)</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Always use <b>WERE</b> for all subjects</div>\n        <div class='cheat-trap'><strong>Trap:</strong> Never use 'was' in hypothetical conditions.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Past Perfect with Two Past Actions</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Earlier Action = <b>had + V3</b>; Later Action = <b>V2</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Putting both actions in simple past.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Ago / Yesterday with Verbs</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Strictly requires <b>Simple Past (V2)</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Never use Present Perfect (*'I have seen him yesterday'*).</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Await / Despite / Comprise</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Await = wait for (NO 'for'); Despite (NO 'of'); Comprise (NO 'of')</div>\n        <div class='cheat-trap'><strong>Trap:</strong> Writing 'await for', 'despite of', or 'comprises of'.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Order of Multiple Adverbs</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Follow <b>M-P-T</b>: Manner -> Place -> Time</div>\n        <div class='cheat-trap'><strong>Trap:</strong> Scattering adverbs randomly.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Enough placement</div>\n        <div class='cheat-rule'><strong>Rule:</strong> <b>Positive Degree Adj + enough</b> | <b>enough + Noun</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Saying 'enough wise' or 'wiser enough'.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Between... and vs From... to</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Between pairs with <b>AND</b>; From pairs with <b>TO</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Writing 'between 2 PM to 5 PM'.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Comparative Exclusion ('Other')</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Same category requires <b>'than any other'</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Comparing an item with itself (*'Iron is harder than any metal'*).</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Pseudo-Subject 'It is / was'</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Followed by <b>Subjective Pronoun (I, he, she)</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Writing 'It was me who did it'.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Else vs Other</div>\n        <div class='cheat-rule'><strong>Rule:</strong> <b>Else takes BUT</b>; <b>Other / Otherwise takes THAN</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Writing 'nothing else than' or 'no other but'.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Compound Indefinite + Else</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Apostrophe on else: <b>somebody else's</b></div>\n        <div class='cheat-trap'><strong>Trap:</strong> Writing 'somebody's else'.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Predicative-Only Adjectives</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Words like <i>asleep, awake, afraid, alike</i> cannot precede nouns</div>\n        <div class='cheat-trap'><strong>Trap:</strong> Writing 'an asleep baby'; say 'a sleeping baby'.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Uncountable Nouns</div>\n        <div class='cheat-rule'><strong>Rule:</strong> <i>scenery, furniture, advice, information, bread</i> have NO plural</div>\n        <div class='cheat-trap'><strong>Trap:</strong> Writing 'sceneries' or 'many furnitures'.</div>\n    </div>\n    \n    <div class='cheat-item'>\n        <div class='cheat-title'>Apostrophe on Plural ending in -s</div>\n        <div class='cheat-rule'><strong>Rule:</strong> Add <b>only apostrophe (')</b> without second 's'</div>\n        <div class='cheat-trap'><strong>Trap:</strong> Writing 'boys's school' or 'girls's hostel'.</div>\n    </div>\n    </div></div>"}, {"type": "rules", "page_num": 4, "title": "Rules 1\u20134", "html": "<div class='page-content'><div class='page-header-title'>Rules 1 to 4</div><div class='rules-container'>\n        <div class='rule-card' id='rule-1'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 1</span>\n                <span class='rule-name'>Each vs. Every</span>\n            </div>\n            <div class='rule-concept'>'Each' focuses on individual members (used for 2 or more; acts as adjective or pronoun). 'Every' focuses on the group collectively (used for more than 2; acts only as an adjective). Both take a singular countable noun and a singular verb.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Each / Every + Singular Noun + Singular Verb | Each of + Plural Noun + Singular Verb</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Each of the participants have received their certificate.</s></div><div class='eg eg-right'>&#10003; Each of the participants has received his or her certificate.</div><div class='eg eg-right'>&#10003; Every student was present in the auditorium.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Every of' does not exist in English because 'every' cannot be a pronoun. Use 'Each of' or 'Every one of'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-2'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 2</span>\n                <span class='rule-name'>Both and Not Cannot Co-exist</span>\n            </div>\n            <div class='rule-concept'>'Both' and 'not' must never be used together to express negative meaning because of logical contradiction. Use 'Neither... nor' instead.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Do not use 'Both... not' -> Use 'Neither of' or 'Neither... nor'</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Both Rohan and Sohan did not attend the conference.</s></div><div class='eg eg-right'>&#10003; Neither Rohan nor Sohan attended the conference.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Both' is strictly positive (paired with 'and'). For two entities in negative sentences, always use 'Neither'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-3'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 3</span>\n                <span class='rule-name'>Proximity Rule with Correlative Conjunctions</span>\n            </div>\n            <div class='rule-concept'>When two subjects are joined by 'Either... or', 'Neither... nor', 'Not only... but also', 'Or', or 'Nor', the finite verb agrees with the subject closest to it.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Neither S1 nor S2 + Verb (agrees with S2 in number and person)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Neither the manager nor the employees was present.</s></div><div class='eg eg-right'>&#10003; Neither the manager nor the employees were present.</div><div class='eg eg-right'>&#10003; Neither the employees nor the manager was present.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Always check the subject immediately adjacent to the auxiliary/main verb.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-4'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 4</span>\n                <span class='rule-name'>Prepositional Connectors and First Subject Priority</span>\n            </div>\n            <div class='rule-concept'>When two subjects are joined by 'as well as', 'along with', 'together with', 'with', 'in addition to', 'accompanied by', 'besides', 'except', 'rather than', or 'like/unlike', the verb agrees with the first subject.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Subject 1 + [as well as / along with / etc.] + Subject 2 + Verb (agrees with Subject 1)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; The Prime Minister, along with his cabinet colleagues, were welcomed.</s></div><div class='eg eg-right'>&#10003; The Prime Minister, along with his cabinet colleagues, was welcomed.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Do not be distracted by the plural noun immediately before the verb inside the parenthetical phrase.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 5, "title": "Rules 5\u20138", "html": "<div class='page-content'><div class='page-header-title'>Rules 5 to 8</div><div class='rules-container'>\n        <div class='rule-card' id='rule-5'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 5</span>\n                <span class='rule-name'>'One of the' Singular vs. Plural Verb Rules</span>\n            </div>\n            <div class='rule-concept'>Standard 'One of the' takes a plural noun and singular verb. However, when followed by a relative pronoun (who/which/that), the verb becomes plural because its antecedent is the plural noun. If preceded by 'the only', it takes a singular verb.</div>\n            <div class='rule-formula'><strong>Formula:</strong> One of the + Plural Noun + Singular Verb | One of the + Plural Noun + who/that + Plural Verb | The only one of the + Plural Noun + who/that + Singular Verb</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; One of the candidates is selected.</div><div class='eg eg-right'>&#10003; He is one of those players who have scored a century on debut.</div><div class='eg eg-right'>&#10003; This is the only one of his novels that is worth reading.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Watch for 'the only'\u2014it overrides the relative pronoun rule and forces a singular verb.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-6'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 6</span>\n                <span class='rule-name'>Units of Distance, Money, Time, and Weight</span>\n            </div>\n            <div class='rule-concept'>When a specific amount of money, distance, time, or weight is considered as a single collective unit, it takes a singular verb. If considered as divided or individual items, it takes a plural verb.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Specified Quantity/Unit as a Whole -> Singular Verb | Divided/Dispersed Units -> Plural Verb</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; Ten thousand rupees is a reasonable fee for this course.</div><div class='eg eg-right'>&#10003; Ten thousand rupees were distributed among the flood victims.</div><div class='eg eg-right'>&#10003; Five miles is an easy distance to cover on foot.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Look at the context: is the amount viewed as a lump sum/total distance, or are units being spent/distributed individually?</div>\n        </div>\n        \n        <div class='rule-card' id='rule-7'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 7</span>\n                <span class='rule-name'>'A Number of' vs. 'The Number of'</span>\n            </div>\n            <div class='rule-concept'>'A number of' means 'many' and takes a plural verb. 'The number of' denotes a specific count/figure and takes a singular verb.</div>\n            <div class='rule-formula'><strong>Formula:</strong> A number of + Plural Noun + Plural Verb | The number of + Plural Noun + Singular Verb</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; A number of students is protesting outside.</s></div><div class='eg eg-right'>&#10003; A number of students are protesting outside.</div><div class='eg eg-right'>&#10003; The number of accidents on this highway has decreased.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Remember: A = Plural (A lot), The = Singular (The exact figure).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-8'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 8</span>\n                <span class='rule-name'>'Many' vs. 'Many a / an'</span>\n            </div>\n            <div class='rule-concept'>'Many' is followed by a plural countable noun and a plural verb. 'Many a' or 'Many an' is followed by a singular countable noun and a singular verb.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Many + Plural Noun + Plural Verb | Many a/an + Singular Noun + Singular Verb</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Many a soldiers have died on the battlefield.</s></div><div class='eg eg-right'>&#10003; Many a soldier has died on the battlefield.</div><div class='eg eg-right'>&#10003; Many soldiers have died on the battlefield.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Many a' means the same as 'many', but structurally requires strict singular agreement.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 6, "title": "Rules 9\u201312", "html": "<div class='page-content'><div class='page-header-title'>Rules 9 to 12</div><div class='rules-container'>\n        <div class='rule-card' id='rule-9'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 9</span>\n                <span class='rule-name'>Fractions, Percentages, and Proportions</span>\n            </div>\n            <div class='rule-concept'>With expressions like 'half of', 'two-thirds of', 'a percentage of', 'most of', or 'some of', the verb agrees with the noun in the prepositional phrase.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Fraction/Percentage of + Uncountable Noun -> Singular Verb | Fraction/Percentage of + Plural Noun -> Plural Verb</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; Two-thirds of the book has been reviewed.</div><div class='eg eg-right'>&#10003; Two-thirds of the books have been reviewed.</div><div class='eg eg-right'>&#10003; Eighty percent of the crop was destroyed.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> The fraction itself does not determine the verb; the noun following 'of' does.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-10'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 10</span>\n                <span class='rule-name'>'More than one' vs. 'More [nouns] than one'</span>\n            </div>\n            <div class='rule-concept'>'More than one' is followed by a singular noun and singular verb. 'More [plural noun] than one' is followed by a plural verb.</div>\n            <div class='rule-formula'><strong>Formula:</strong> More than one + Singular Noun + Singular Verb | More + Plural Noun + than one + Plural Verb</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; More than one person was involved in the conspiracy.</div><div class='eg eg-right'>&#10003; More persons than one were involved in the conspiracy.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Pay close attention to where the noun sits relative to 'than one'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-11'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 11</span>\n                <span class='rule-name'>Collective Nouns: Unanimous vs. Divided</span>\n            </div>\n            <div class='rule-concept'>When a collective noun (jury, committee, team, board, audience) acts unanimously as one body, use a singular verb and singular pronoun (it/its). When members act individually or disagree, use a plural verb and plural pronoun (they/their).</div>\n            <div class='rule-formula'><strong>Formula:</strong> Unified Action -> Singular Verb & Pronoun | Divided / Individual Action -> Plural Verb & Pronoun</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; The jury has delivered its verdict unanimously.</div><div class='eg eg-right'>&#10003; The jury were divided in their opinions.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Never mix pronouns and verbs (e.g., 'The committee has taken their decision' is incorrect).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-12'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 12</span>\n                <span class='rule-name'>Nouns Joined by 'And' Expressing a Single Idea</span>\n            </div>\n            <div class='rule-concept'>When two singular nouns joined by 'and' express a single unified compound concept, profession, or food item, they take a singular verb.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Noun 1 + and + Noun 2 (single idea/pair) + Singular Verb</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; Bread and butter is wholesome food.</div><div class='eg eg-right'>&#10003; Slow and steady wins the race.</div><div class='eg eg-note'>&bull; Note: Bread and butter are sold in this grocery store. (Two separate commodities)</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Common singular pairs: Rice and curry, Horse and carriage, Hammer and sickle, Crown and glory.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 7, "title": "Rules 13\u201316", "html": "<div class='page-content'><div class='page-header-title'>Rules 13 to 16</div><div class='rules-container'>\n        <div class='rule-card' id='rule-13'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 13</span>\n                <span class='rule-name'>Subjective vs. Objective Case After Prepositions</span>\n            </div>\n            <div class='rule-concept'>Any pronoun following a preposition (including 'between', 'except', 'but', 'for', 'with') must always be in the Objective Case.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Preposition + Objective Case Pronoun (me, us, him, her, them, whom)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; There is no dispute between you and I.</s></div><div class='eg eg-right'>&#10003; There is no dispute between you and me.</div><div class='eg eg-wrong'><s>&times; Everyone attended the meeting except she.</s></div><div class='eg eg-right'>&#10003; Everyone attended the meeting except her.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Between you and I' is one of the most common conversational errors in exams.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-14'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 14</span>\n                <span class='rule-name'>'Who' (Subject) vs. 'Whom' (Object)</span>\n            </div>\n            <div class='rule-concept'>'Who' is a subjective pronoun that performs the action (he/she/they). 'Whom' is an objective pronoun that receives the action (him/her/them). Count clauses: if finite verbs outnumber stated subjects, use 'Who'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Who + Verb (Subject role) | Whom + Subject + Verb (Object role)</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; The woman who called you is my manager.</div><div class='eg eg-right'>&#10003; The woman whom you called is my manager.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Do not let parenthetical clauses like 'I think' or 'they believe' mislead you into using 'whom' when the pronoun is the true verb subject.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-15'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 15</span>\n                <span class='rule-name'>Mandatory Use of Relative Pronoun 'That'</span>\n            </div>\n            <div class='rule-concept'>Always use 'that' instead of 'who' or 'which' after: superlative adjectives, words like 'all', 'any', 'none', 'only', 'the same', 'little', 'few', 'much', 'everything', 'nothing', and when combining a person and an animal/object.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Superlative / Indefinite Word / Person + Animal -> that</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; This is the best book which I have ever read.</s></div><div class='eg eg-right'>&#10003; This is the best book that I have ever read.</div><div class='eg eg-right'>&#10003; All that glitters is not gold.</div><div class='eg eg-right'>&#10003; The boy and his dog that crossed the road were rescued.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Which' is incorrect after 'only', 'all', or superlative adjectives.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-16'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 16</span>\n                <span class='rule-name'>Order of Personal Pronouns: 2-3-1 vs. 1-2-3</span>\n            </div>\n            <div class='rule-concept'>In normal, polite, or positive contexts with multiple personal pronouns, follow the 2-3-1 rule (Second Person -> Third Person -> First Person). In negative contexts (confessing guilt, mistake, crime) or when pronouns are plural, follow the 1-2-3 rule.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Pleasant / Normal -> 2nd, 3rd, 1st (You, he, and I) | Fault / Blame / Plural -> 1st, 2nd, 3rd (I, you, and he / We, you, and they)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; I, you, and he will attend the seminar.</s></div><div class='eg eg-right'>&#10003; You, he, and I will attend the seminar.</div><div class='eg eg-right'>&#10003; I, you, and he are responsible for this financial loss.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Always check whether the sentence conveys an accomplishment or an admission of guilt.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 8, "title": "Rules 17\u201320", "html": "<div class='page-content'><div class='page-header-title'>Rules 17 to 20</div><div class='rules-container'>\n        <div class='rule-card' id='rule-17'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 17</span>\n                <span class='rule-name'>Pronoun Case in Comparisons with 'Than' and 'As'</span>\n            </div>\n            <div class='rule-concept'>When comparing subjects, the pronoun following 'than' or 'as' must be in the subjective case because it represents an elliptical clause with an implied verb.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Subject 1 + Verb + [than / as... as] + Subjective Pronoun (+ implied verb)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; She is faster than me.</s></div><div class='eg eg-right'>&#10003; She is faster than I (am).</div><div class='eg eg-right'>&#10003; He respects you as much as he respects me. (Comparing objects)</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> In colloquial speech 'than me' is common, but in formal examinations only the subjective case is accepted when comparing subjects.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-18'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 18</span>\n                <span class='rule-name'>Consistency with Indefinite Pronoun 'One'</span>\n            </div>\n            <div class='rule-concept'>When 'one' is used as an indefinite subject meaning 'anyone', it must be consistently followed by 'one', 'one's', or 'oneself' throughout the entire sentence, never by 'he', 'his', or 'himself'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> One -> one's (possessive) -> oneself (reflexive)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; One should do his duty diligently.</s></div><div class='eg eg-right'>&#10003; One should do one's duty diligently.</div><div class='eg eg-wrong'><s>&times; One must not boast of himself.</s></div><div class='eg eg-right'>&#10003; One must not boast of oneself.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Do not switch from 'one' to 'his' or 'he' mid-sentence.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-19'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 19</span>\n                <span class='rule-name'>Reflexive Pronouns with Transitive Verbs</span>\n            </div>\n            <div class='rule-concept'>Verbs like 'avail', 'adapt', 'adjust', 'absent', 'reconcile', 'enjoy', 'introduce', and 'exert' require a reflexive pronoun if no direct object follows. Conversely, verbs like 'keep', 'break', 'turn', 'stop', 'bathe', 'hide', 'qualify' do not take reflexive pronouns.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Transitive Verb without Direct Object + Reflexive Pronoun (myself, himself, etc.)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He absented from the office yesterday.</s></div><div class='eg eg-right'>&#10003; He absented himself from the office yesterday.</div><div class='eg eg-wrong'><s>&times; He hid himself behind the curtain.</s></div><div class='eg eg-right'>&#10003; He hid behind the curtain.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Enjoy' takes a reflexive pronoun only when no object is mentioned (*We enjoyed ourselves at the party*, but *We enjoyed the movie*).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-20'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 20</span>\n                <span class='rule-name'>Pseudo-Subject 'It' and Subjective Pronoun Case</span>\n            </div>\n            <div class='rule-concept'>When 'It' acts as an introductory pseudo-subject followed by 'is' or 'was', the predicate pronoun must be in the Subjective Case, and any subsequent relative clause verb agrees with that pronoun.</div>\n            <div class='rule-formula'><strong>Formula:</strong> It is / was + Subjective Pronoun (I, he, she, they) + who/that + Verb</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; It was me who solved the puzzle.</s></div><div class='eg eg-right'>&#10003; It was I who solved the puzzle.</div><div class='eg eg-wrong'><s>&times; It is I who is responsible for the error.</s></div><div class='eg eg-right'>&#10003; It is I who am responsible for the error.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Always ensure the verb following 'who' agrees with the subjective pronoun preceding it.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 9, "title": "Rules 21\u201324", "html": "<div class='page-content'><div class='page-header-title'>Rules 21 to 24</div><div class='rules-container'>\n        <div class='rule-card' id='rule-21'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 21</span>\n                <span class='rule-name'>Parallelism with Correlative Conjunctions</span>\n            </div>\n            <div class='rule-concept'>Elements joined by correlative conjunctions (not only... but also, either... or, neither... nor, both... and) must belong to the exact same grammatical category (verb with verb, noun with noun, adjective with adjective).</div>\n            <div class='rule-formula'><strong>Formula:</strong> Correlative 1 + Grammatical Form X ... Correlative 2 + Grammatical Form X</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He not only lost his wallet but also his watch.</s></div><div class='eg eg-right'>&#10003; He lost not only his wallet but also his watch.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Place the first conjunction immediately before the element being paralleled.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-22'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 22</span>\n                <span class='rule-name'>Inversion After Negative and Restrictive Adverbs</span>\n            </div>\n            <div class='rule-concept'>When a sentence begins with a negative or restrictive adverb (Hardly, Scarcely, Barely, Seldom, Rarely, Little, Never, Under no circumstances), use inverted word order (Auxiliary Verb + Subject + Main Verb).</div>\n            <div class='rule-formula'><strong>Formula:</strong> Negative Adverb + Auxiliary Verb + Subject + Main Verb</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Seldom I have witnessed such courage.</s></div><div class='eg eg-right'>&#10003; Seldom have I witnessed such courage.</div><div class='eg eg-wrong'><s>&times; Rarely he visits his ancestral home.</s></div><div class='eg eg-right'>&#10003; Rarely does he visit his ancestral home.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Do not forget the helping verb (do/does/did/has/have/had).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-23'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 23</span>\n                <span class='rule-name'>Correlative Time Connectors: Hardly/Scarcely with 'When', No Sooner with 'Than'</span>\n            </div>\n            <div class='rule-concept'>'Hardly' and 'Scarcely' are paired with 'when' (or 'before'). 'No sooner' is paired with 'than'. Both enforce subject-auxiliary inversion.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Hardly / Scarcely + had + S + V3 ... when + Past Simple | No sooner + had/did + S + V3/V1 ... than + Past Simple</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Hardly had I entered the room than the lights went out.</s></div><div class='eg eg-right'>&#10003; Hardly had I entered the room when the lights went out.</div><div class='eg eg-wrong'><s>&times; No sooner did the train arrive when passengers rushed in.</s></div><div class='eg eg-right'>&#10003; No sooner did the train arrive than passengers rushed in.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Never pair 'No sooner' with 'when' or 'then', and never pair 'Hardly' with 'than'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-24'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 24</span>\n                <span class='rule-name'>'Few' vs. 'Little' Formulations</span>\n            </div>\n            <div class='rule-concept'>'Few' modifies countable nouns (Few = almost none; A few = a small number; The few = all of that small number). 'Little' modifies uncountable nouns (Little = almost none; A little = a small amount; The little = all of that small amount).</div>\n            <div class='rule-formula'><strong>Formula:</strong> Few / A few / The few + Countable Noun | Little / A little / The little + Uncountable Noun</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; A few friends came to help me move.</div><div class='eg eg-right'>&#10003; There is little hope of his recovery (almost no hope).</div><div class='eg eg-right'>&#10003; He spent the little money he had on medicines.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Few' and 'Little' without articles convey an entirely negative sense.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 10, "title": "Rules 25\u201328", "html": "<div class='page-content'><div class='page-header-title'>Rules 25 to 28</div><div class='rules-container'>\n        <div class='rule-card' id='rule-25'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 25</span>\n                <span class='rule-name'>Latin Adjectives Ending in '-ior' Take 'To'</span>\n            </div>\n            <div class='rule-concept'>Adjectives of Latin origin ending in '-ior' (senior, junior, superior, inferior, prior, anterior, posterior) along with 'prefer' and 'preferable' take the preposition 'to', never 'than'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Senior / Junior / Superior / Inferior / Preferable + to</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He is senior than me in service.</s></div><div class='eg eg-right'>&#10003; He is senior to me in service.</div><div class='eg eg-wrong'><s>&times; Milk is more preferable than tea.</s></div><div class='eg eg-right'>&#10003; Milk is preferable to tea.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Never use 'more' with 'preferable' or Latin '-ior' adjectives.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-26'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 26</span>\n                <span class='rule-name'>Absolute / Non-Gradable Adjectives</span>\n            </div>\n            <div class='rule-concept'>Adjectives that represent absolute or extreme states (unique, perfect, universal, complete, circular, extreme, dead, impossible, round) cannot take comparative or superlative modifiers like 'more', 'most', or 'very'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Non-gradable adjective -> No 'more' / 'most' / 'very'</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; This is the most unique idea I have heard.</s></div><div class='eg eg-right'>&#10003; This is a unique idea.</div><div class='eg eg-wrong'><s>&times; The drawing was more circular.</s></div><div class='eg eg-right'>&#10003; The drawing was circular.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Expressions like 'more perfect' or 'most unique' are logical errors in exam questions.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-27'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 27</span>\n                <span class='rule-name'>Double Comparatives and Superlatives Prohibited</span>\n            </div>\n            <div class='rule-concept'>Never use two comparative degrees or two superlative degrees together in the same adjective phrase.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Avoid 'more better', 'more taller', 'most cleanest'</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He is more taller than his elder brother.</s></div><div class='eg eg-right'>&#10003; He is taller than his elder brother.</div><div class='eg eg-wrong'><s>&times; This is the most finest monument in the city.</s></div><div class='eg eg-right'>&#10003; This is the finest monument in the city.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> If an adjective has an -er or -est form, never precede it with more or most.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-28'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 28</span>\n                <span class='rule-name'>Parallel Increase / Decrease: 'The more..., the more...'</span>\n            </div>\n            <div class='rule-concept'>When two related attributes or actions increase or decrease in tandem, both comparative clauses must begin with the definite article 'the'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> The + Comparative Degree ..., The + Comparative Degree ...</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Higher you climb, colder you feel.</s></div><div class='eg eg-right'>&#10003; The higher you climb, the colder you feel.</div><div class='eg eg-right'>&#10003; The more you study, the more confident you become.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Make sure 'the' is present before both comparative adjectives.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 11, "title": "Rules 29\u201332", "html": "<div class='page-content'><div class='page-header-title'>Rules 29 to 32</div><div class='rules-container'>\n        <div class='rule-card' id='rule-29'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 29</span>\n                <span class='rule-name'>Illogical Comparison: 'That of' and 'Those of'</span>\n            </div>\n            <div class='rule-concept'>Comparisons must be made between logically comparable entities. To prevent comparing an attribute of an entity to the entity itself, use 'that of' (singular) or 'those of' (plural).</div>\n            <div class='rule-formula'><strong>Formula:</strong> Attribute of A + comparison + that of (singular) / those of (plural) + B</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; The climate of Bengaluru is cooler than Chennai.</s></div><div class='eg eg-right'>&#10003; The climate of Bengaluru is cooler than that of Chennai.</div><div class='eg eg-wrong'><s>&times; The streets of Tokyo are cleaner than New York.</s></div><div class='eg eg-right'>&#10003; The streets of Tokyo are cleaner than those of New York.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Check whether you are comparing things of the same nature (climate to climate, streets to streets).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-30'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 30</span>\n                <span class='rule-name'>'Elder / Eldest' vs. 'Older / Oldest'</span>\n            </div>\n            <div class='rule-concept'>'Elder' and 'Eldest' are used exclusively for blood relatives within the immediate family and are never followed by 'than'. 'Older' and 'Oldest' apply to people outside the family, animals, and inanimate objects, and can be paired with 'than'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Elder (blood relative, no 'than') | Older than (general age comparison)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He is elder than his friend.</s></div><div class='eg eg-right'>&#10003; He is older than his friend.</div><div class='eg eg-right'>&#10003; Suman is my elder sister.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Never say 'elder than'. If 'than' is present, the word must be 'older'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-31'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 31</span>\n                <span class='rule-name'>First Conditional: Simple Present in Condition Clauses</span>\n            </div>\n            <div class='rule-concept'>In real future conditional sentences, the subordinate clause (if, when, as soon as, unless, until) must be in the Simple Present tense, while the main result clause takes future modal auxiliaries (will/can/may + V1).</div>\n            <div class='rule-formula'><strong>Formula:</strong> If + Simple Present (V1/V1+s/es), Main Clause (will/shall/can + V1)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; If you will come tomorrow, we will discuss the project.</s></div><div class='eg eg-right'>&#10003; If you come tomorrow, we will discuss the project.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Never use 'will', 'shall', or 'would' inside the conditional or time clause.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-32'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 32</span>\n                <span class='rule-name'>Second Conditional: Hypothetical Subjunctive 'Were'</span>\n            </div>\n            <div class='rule-concept'>For unreal, imaginary, or contrary-to-fact situations in the present or future, use the Simple Past (V2) in the if-clause and 'would/could/might + V1' in the main clause. If using the verb 'to be', always use 'were' for all subjects.</div>\n            <div class='rule-formula'><strong>Formula:</strong> If + Subject + were / V2, Subject + would / could + V1</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; If I was the king, I would remove poverty.</s></div><div class='eg eg-right'>&#10003; If I were the king, I would remove poverty.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Was' is never used in unreal conditional clauses, regardless of whether the subject is singular (I, he, she, it).</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 12, "title": "Rules 33\u201336", "html": "<div class='page-content'><div class='page-header-title'>Rules 33 to 36</div><div class='rules-container'>\n        <div class='rule-card' id='rule-33'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 33</span>\n                <span class='rule-name'>Third Conditional: Past Unfulfilled Actions</span>\n            </div>\n            <div class='rule-concept'>Used for impossible past conditions that did not happen. The condition takes the Past Perfect (had + V3) and the main clause takes 'would have / could have / might have + V3'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> If + had + V3, would have / could have + V3 | Had + S + V3, would have + V3 (inverted)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; If he worked hard, he would have cleared the examination.</s></div><div class='eg eg-right'>&#10003; If he had worked hard, he would have cleared the examination.</div><div class='eg eg-right'>&#10003; Had she reached on time, she would have caught the flight.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Do not mix second and third conditionals (e.g., 'If had + V3 ... would + V1').</div>\n        </div>\n        \n        <div class='rule-card' id='rule-34'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 34</span>\n                <span class='rule-name'>Subjunctive with 'As if' and 'As though'</span>\n            </div>\n            <div class='rule-concept'>When expressing an imaginary or simulated condition with 'as if' or 'as though', use the past subjunctive ('were' for states, 'past perfect' for earlier unfulfilled actions).</div>\n            <div class='rule-formula'><strong>Formula:</strong> Subject + Verb + as if / as though + Subject + were / had + V3</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He talks as if he knows everything.</s></div><div class='eg eg-right'>&#10003; He talks as if he knew everything (or: as if he were an expert).</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Even if the introductory verb is in the present tense, the subjunctive clause requires a past form.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-35'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 35</span>\n                <span class='rule-name'>'It is high time' / 'It is about time'</span>\n            </div>\n            <div class='rule-concept'>When the phrase 'It is time' or 'It is high time' is followed directly by a subject, the following verb must be in the Simple Past (V2). If followed by an infinitive, use 'to + V1'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> It is high time + Subject + Simple Past (V2) | It is time + to + V1</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; It is high time we start preparing for the exams.</s></div><div class='eg eg-right'>&#10003; It is high time we started preparing for the exams.</div><div class='eg eg-right'>&#10003; It is time to leave for the station.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Never use the present tense or modals like 'should' immediately after 'It is high time + Subject'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-36'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 36</span>\n                <span class='rule-name'>Gerund Following Prepositional 'To' Phrases</span>\n            </div>\n            <div class='rule-concept'>Phrases where 'to' is a preposition (looking forward to, accustomed to, with a view to, addicted to, habituated to, prone to, devoted to, given to, in addition to) must be followed by a Gerund (V1 + ing), not a bare verb.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Phrase with prepositional 'to' + Gerund (V1 + ing)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; I am looking forward to meet the delegates.</s></div><div class='eg eg-right'>&#10003; I am looking forward to meeting the delegates.</div><div class='eg eg-wrong'><s>&times; He went to Delhi with a view to attend the seminar.</s></div><div class='eg eg-right'>&#10003; He went to Delhi with a view to attending the seminar.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Do not confuse the preposition 'to' in these fixed phrases with the infinitive particle 'to'.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 13, "title": "Rules 37\u201340", "html": "<div class='page-content'><div class='page-header-title'>Rules 37 to 40</div><div class='rules-container'>\n        <div class='rule-card' id='rule-37'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 37</span>\n                <span class='rule-name'>'Used to + V1' vs. 'Be/Get used to + V1+ing'</span>\n            </div>\n            <div class='rule-concept'>'Subject + used to + V1' denotes a past discontinued habit. 'Subject + is/am/are/was/were/get + used to + V1+ing' denotes being accustomed to an activity.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Subject + used to + V1 (past habit) | Subject + [be / get] + used to + Gerund (accustomed)</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; He used to wake up at 5 AM when he was a student.</div><div class='eg eg-right'>&#10003; He is used to waking up at 5 AM now.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Look for the auxiliary verb (be/get) before 'used to'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-38'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 38</span>\n                <span class='rule-name'>Stative Verbs and Non-Continuous Usage</span>\n            </div>\n            <div class='rule-concept'>Verbs denoting states, mental perception, senses, emotions, and possession (see, hear, smell, taste, know, understand, believe, love, hate, own, belong, possess) are not used in continuous tenses in their stative sense.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Stative Verb -> Simple Present (not Present Continuous)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; I am understanding your viewpoint clearly.</s></div><div class='eg eg-right'>&#10003; I understand your viewpoint clearly.</div><div class='eg eg-wrong'><s>&times; This bungalow is belonging to an NRI.</s></div><div class='eg eg-right'>&#10003; This bungalow belongs to an NRI.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Continuous form is permitted only when these verbs indicate a deliberate, dynamic action (e.g., 'The chef is tasting the soup').</div>\n        </div>\n        \n        <div class='rule-card' id='rule-39'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 39</span>\n                <span class='rule-name'>Possessive Case Before a Gerund</span>\n            </div>\n            <div class='rule-concept'>A noun or pronoun modifying a gerund (V1+ing acting as a noun) must be in the possessive case (my, your, his, her, their, our, Ram's), not the objective case.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Possessive Adjective / Noun + Gerund (V1 + ing)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; My parents objected to me staying out late.</s></div><div class='eg eg-right'>&#10003; My parents objected to my staying out late.</div><div class='eg eg-wrong'><s>&times; I appreciated him helping the needy.</s></div><div class='eg eg-right'>&#10003; I appreciated his helping the needy.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> In error detection questions, replace objective pronouns (me, him, them) before an -ing noun with possessives (my, his, their).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-40'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 40</span>\n                <span class='rule-name'>Bare Infinitives with Causative and Perception Verbs</span>\n            </div>\n            <div class='rule-concept'>In active voice, verbs like 'make', 'let', 'bid', 'see', 'hear', 'watch', 'feel' are followed by a bare infinitive (V1 without 'to'). In passive voice, 'make' takes 'to + V1' ('let' remains bare).</div>\n            <div class='rule-formula'><strong>Formula:</strong> Active: Subject + make/let/see + Object + V1 | Passive: Subject + be made + to + V1</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; The teacher made the student to apologize.</s></div><div class='eg eg-right'>&#10003; The teacher made the student apologize.</div><div class='eg eg-right'>&#10003; The student was made to apologize by the teacher.</div><div class='eg eg-right'>&#10003; Let him go.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Never add 'to' after 'let', whether active or passive.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 14, "title": "Rules 41\u201344", "html": "<div class='page-content'><div class='page-header-title'>Rules 41 to 44</div><div class='rules-container'>\n        <div class='rule-card' id='rule-41'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 41</span>\n                <span class='rule-name'>Bare Infinitives After Modal Idioms</span>\n            </div>\n            <div class='rule-concept'>Always use a bare infinitive (V1) after expressions like 'had better', 'would rather', 'had sooner', 'sooner than', 'rather than', and 'but/except' when preceded by a form of 'do'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Had better / Would rather + V1 (no 'to')</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; You had better to take an umbrella.</s></div><div class='eg eg-right'>&#10003; You had better take an umbrella.</div><div class='eg eg-wrong'><s>&times; He did nothing but to complain.</s></div><div class='eg eg-right'>&#10003; He did nothing but complain.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Had better' looks like a past perfect construction, but it refers to the present/future and requires a bare verb.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-42'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 42</span>\n                <span class='rule-name'>Avoiding Split Infinitives in Formal English</span>\n            </div>\n            <div class='rule-concept'>In formal examination standards, avoid inserting adverbs between the particle 'to' and the bare verb 'V1'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> to + V1 + Adverb (or Adverb + to + V1)</div>\n            <div class='rule-examples'><div class='eg eg-note'>&bull; Awkward: You need to carefully review the contract.</div><div class='eg eg-note'>&bull; Preferred: You need to review the contract carefully.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Keep the infinitive unit ('to read', 'to write') intact.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-43'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 43</span>\n                <span class='rule-name'>Dangling / Unattached Participles</span>\n            </div>\n            <div class='rule-concept'>A participial clause at the start of a sentence must logically relate to the grammatical subject that follows. If the subject cannot perform that participial action, provide an explicit subject for the participle.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Participle Phrase, Subject (must be the doer of the participle) + Verb</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Walking in the park, a snake bit him.</s></div><div class='eg eg-right'>&#10003; While he was walking in the park, a snake bit him.</div><div class='eg eg-wrong'><s>&times; Being a sunny day, we decided to go for a swim.</s></div><div class='eg eg-right'>&#10003; It being a sunny day, we decided to go for a swim.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Watch out for 'Being a...' sentences without 'It' as an introductory pronoun.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-44'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 44</span>\n                <span class='rule-name'>Sequence of Past Actions: Past Perfect vs. Simple Past</span>\n            </div>\n            <div class='rule-concept'>When two actions happened in the past, the earlier completed action takes the Past Perfect (had + V3) and the subsequent action takes the Simple Past (V2).</div>\n            <div class='rule-formula'><strong>Formula:</strong> Earlier Action: had + V3 ... Later Action: Simple Past (V2)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; The train left before I reached the platform.</s></div><div class='eg eg-right'>&#10003; The train had left before I reached the platform.</div><div class='eg eg-right'>&#10003; After the chief guest had delivered the speech, the ceremony ended.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Do not put both past actions in the Simple Past if the time sequence is explicit.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 15, "title": "Rules 45\u201348", "html": "<div class='page-content'><div class='page-header-title'>Rules 45 to 48</div><div class='rules-container'>\n        <div class='rule-card' id='rule-45'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 45</span>\n                <span class='rule-name'>'Since' as a Time Conjunction</span>\n            </div>\n            <div class='rule-concept'>When 'since' denotes time starting from a past moment, the main clause takes the Present Perfect (or Present Perfect Continuous), while the clause introduced by 'since' takes the Simple Past (V2).</div>\n            <div class='rule-formula'><strong>Formula:</strong> Present Perfect + since + Simple Past (V2)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Two years passed since he left the country.</s></div><div class='eg eg-right'>&#10003; Two years have passed since he left the country.</div><div class='eg eg-right'>&#10003; I have not seen him since he graduated.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Do not use Simple Past in the main clause before 'since'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-46'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 46</span>\n                <span class='rule-name'>'Since' vs. 'For' Time Expressions</span>\n            </div>\n            <div class='rule-concept'>'Since' marks a specific starting point in time (since 1990, since Monday, since morning, since 4 PM). 'For' marks a duration or period of time (for three hours, for two days, for ten years).</div>\n            <div class='rule-formula'><strong>Formula:</strong> Since + Point in Time | For + Period of Time</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; She has been studying since 8 AM.</div><div class='eg eg-right'>&#10003; She has been studying for three hours.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Do not use 'since' with durations (e.g., 'since two years' is incorrect).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-47'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 47</span>\n                <span class='rule-name'>Sequence of Tenses with Past Principal Clauses</span>\n            </div>\n            <div class='rule-concept'>When the verb in the principal clause is in the past tense, subordinate clause verbs must also be in the past tense, unless the subordinate clause expresses a universal truth, scientific law, or habitual fact.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Past Main Clause -> Past Subordinate Clause (unless Universal Fact)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He told me that he is going to Mumbai.</s></div><div class='eg eg-right'>&#10003; He told me that he was going to Mumbai.</div><div class='eg eg-right'>&#10003; The teacher explained that the sun rises in the east. (Universal Truth)</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Never change the tense of a universal scientific truth even if introduced by 'said' or 'proved'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-48'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 48</span>\n                <span class='rule-name'>Simple Past Required with Specific Past Time Adverbs</span>\n            </div>\n            <div class='rule-concept'>Never use the Present Perfect tense with adverbs of finished past time (yesterday, ago, last week, in 1947, on Monday). Use the Simple Past (V2).</div>\n            <div class='rule-formula'><strong>Formula:</strong> Past Time Adverbial -> Simple Past (V2), NOT Present Perfect</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; I have received your parcel yesterday.</s></div><div class='eg eg-right'>&#10003; I received your parcel yesterday.</div><div class='eg eg-wrong'><s>&times; He has passed the examination two years ago.</s></div><div class='eg eg-right'>&#10003; He passed the examination two years ago.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> The presence of 'ago' or 'yesterday' strictly forbids 'has/have + V3'.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 16, "title": "Rules 49\u201352", "html": "<div class='page-content'><div class='page-header-title'>Rules 49 to 52</div><div class='rules-container'>\n        <div class='rule-card' id='rule-49'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 49</span>\n                <span class='rule-name'>'Between' vs. 'Among' Distinction</span>\n            </div>\n            <div class='rule-concept'>'Between' is used for two entities, or for more than two when there is a mutual, reciprocal relationship or clear bilateral alliance. 'Among' is used for more than two entities considered collectively as a group.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Between: 2 entities (or reciprocal multiple) | Among: 3+ entities</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; Divide the sweets between the two brothers.</div><div class='eg eg-right'>&#10003; A trade treaty was signed between India, France, and Japan. (Reciprocal Pact)</div><div class='eg eg-right'>&#10003; Distribute the blankets among the villagers.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Between' is completely valid for more than two if mutual reciprocal relationships exist.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-50'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 50</span>\n                <span class='rule-name'>'Beside' vs. 'Besides'</span>\n            </div>\n            <div class='rule-concept'>'Beside' means 'by the side of' or 'adjacent to'. 'Besides' means 'in addition to' or 'apart from'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Beside = Next to | Besides = In addition to</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; She sat beside her mother during the ceremony.</div><div class='eg eg-right'>&#10003; Besides Hindi, she is proficient in English and German.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Check whether the sentence refers to physical location or adding information.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-51'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 51</span>\n                <span class='rule-name'>Transitive Verbs that Forbid Prepositions</span>\n            </div>\n            <div class='rule-concept'>Verbs like 'discuss', 'describe', 'order', 'request', 'reach', 'attack', 'resemble', 'enter', 'comprise', 'accompany', and 'marry' are directly transitive and do not take a preposition before their direct object.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Transitive Verb + Direct Object (NO preposition)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; We discussed about the budget proposal.</s></div><div class='eg eg-right'>&#10003; We discussed the budget proposal.</div><div class='eg eg-wrong'><s>&times; He ordered for two cups of tea.</s></div><div class='eg eg-right'>&#10003; He ordered two cups of tea.</div><div class='eg eg-wrong'><s>&times; The committee comprises of ten experts.</s></div><div class='eg eg-right'>&#10003; The committee comprises ten experts.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Enter into' is permitted only for signing agreements or starting discussions, not for physical entry.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-52'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 52</span>\n                <span class='rule-name'>'Die of' vs. 'Die from'</span>\n            </div>\n            <div class='rule-concept'>Use 'die of' when the death is caused by an internal illness, disease, hunger, thirst, or shame. Use 'die from' when the cause is external or indirect (overwork, wound, food poisoning, snake bite).</div>\n            <div class='rule-formula'><strong>Formula:</strong> Die of + Disease / Hunger / Thirst | Die from + External Cause / Wound / Overwork</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; He died of cancer.</div><div class='eg eg-right'>&#10003; He died from severe blood loss following the accident.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Always examine if the cause is an internal disease (of) or an external injury/factor (from).</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 17, "title": "Rules 53\u201356", "html": "<div class='page-content'><div class='page-header-title'>Rules 53 to 56</div><div class='rules-container'>\n        <div class='rule-card' id='rule-53'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 53</span>\n                <span class='rule-name'>Time Prepositions: 'At', 'On', and 'In'</span>\n            </div>\n            <div class='rule-concept'>'At' is used for exact clock times and specific points (at 5 PM, at noon, at dawn). 'On' is used for days and calendar dates (on Monday, on 15th August). 'In' is used for months, years, seasons, centuries, and broader time periods (in May, in 2026, in winter).</div>\n            <div class='rule-formula'><strong>Formula:</strong> At + Clock Time | On + Day / Date | In + Month / Year / Period</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; The train departs at 6:30 AM.</div><div class='eg eg-right'>&#10003; The conference begins on Tuesday, in November.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Do not use 'on' with parts of the day unless qualified by a specific day (e.g., 'in the morning', but 'on Monday morning').</div>\n        </div>\n        \n        <div class='rule-card' id='rule-54'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 54</span>\n                <span class='rule-name'>'Lest' Requires 'Should' and Forbids 'Not'</span>\n            </div>\n            <div class='rule-concept'>'Lest' means 'for fear that' or 'to prevent that'. Because it carries a negative sense, never use 'not' with it, and always pair it with the modal auxiliary 'should'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Lest + Subject + should + V1 (no 'not')</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Run fast lest you will miss the train.</s></div><div class='eg eg-wrong'><s>&times; Run fast lest you should not miss the train.</s></div><div class='eg eg-right'>&#10003; Run fast lest you should miss the train.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Modals like 'will', 'shall', 'would', or 'may' are strictly forbidden after 'lest'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-55'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 55</span>\n                <span class='rule-name'>'Unless' (Condition) vs. 'Until' (Time)</span>\n            </div>\n            <div class='rule-concept'>'Unless' is conditional ('if not'). 'Until' is temporal ('up to the point in time'). Both are inherently negative; their subordinate clauses must never contain negative words (not, never) or future modals.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Unless + Affirmative Present Clause (Condition) | Until + Affirmative Present Clause (Time)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; You will not succeed unless you do not work hard.</s></div><div class='eg eg-right'>&#10003; You will not succeed unless you work hard.</div><div class='eg eg-wrong'><s>&times; Wait here until I do not return.</s></div><div class='eg eg-right'>&#10003; Wait here until I return.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Identify whether the barrier is a condition to fulfill (unless) or a time moment to reach (until).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-56'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 56</span>\n                <span class='rule-name'>'Although / Even though' Paired with 'Yet' (Never 'But')</span>\n            </div>\n            <div class='rule-concept'>Sentences starting with 'Although' or 'Even though' may use 'yet' or a simple comma to join the independent clause. Using 'but' is a serious grammatical error.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Although / Though ... yet (or comma) [NO 'but']</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Although he worked hard, but he failed.</s></div><div class='eg eg-right'>&#10003; Although he worked hard, yet he failed.</div><div class='eg eg-right'>&#10003; Although he worked hard, he failed.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Cross out 'but' whenever you see 'although' or 'though' starting the sentence.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 18, "title": "Rules 57\u201360", "html": "<div class='page-content'><div class='page-header-title'>Rules 57 to 60</div><div class='rules-container'>\n        <div class='rule-card' id='rule-57'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 57</span>\n                <span class='rule-name'>Strict Prohibition of Double Negatives</span>\n            </div>\n            <div class='rule-concept'>Never combine two negative words in the same clause. Words like 'hardly', 'scarcely', 'barely', 'seldom', 'rarely', 'forbid', 'prohibit', 'deny', 'prevent', and 'refrain' already carry negative meaning.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Negative Word + Affirmative Form (NO not / never / no)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He denied that he had not stolen the cash.</s></div><div class='eg eg-right'>&#10003; He denied that he had stolen the cash.</div><div class='eg eg-wrong'><s>&times; She forbade me not to enter the laboratory.</s></div><div class='eg eg-right'>&#10003; She forbade me to enter the laboratory.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Verbs of denial and prohibition (deny, forbid, prohibit) are intrinsically negative.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-58'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 58</span>\n                <span class='rule-name'>'Doubt' / 'Doubtful' in Affirmative vs. Negative Sentences</span>\n            </div>\n            <div class='rule-concept'>In affirmative sentences, use 'if' or 'whether' after 'doubt' or 'doubtful' because uncertainty is expressed. In negative and interrogative sentences, use 'that' because certainty is established.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Affirmative: doubt / doubtful + if / whether | Negative / Question: doubt / doubtful + that</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; I doubt whether / if he will pass the examination.</div><div class='eg eg-right'>&#10003; I have no doubt that he will pass the examination.</div><div class='eg eg-right'>&#10003; Do you have any doubt that she is sincere?</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Check whether the main sentence affirms doubt or negates doubt.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-59'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 59</span>\n                <span class='rule-name'>Uncountable Nouns Never Take Plural Forms</span>\n            </div>\n            <div class='rule-concept'>Nouns like 'scenery', 'poetry', 'furniture', 'advice', 'information', 'hair', 'luggage', 'baggage', 'machinery', 'stationery', and 'bread' are strictly uncountable. They cannot take '-s/-es' and take singular verbs.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Uncountable Noun -> Singular Verb (NO a/an, NO plural -s)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; The sceneries of the Himalayas are picturesque.</s></div><div class='eg eg-right'>&#10003; The scenery of the Himalayas is picturesque.</div><div class='eg eg-wrong'><s>&times; He gave me many advices.</s></div><div class='eg eg-right'>&#10003; He gave me many pieces of advice.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> To pluralize their meaning, use counters: 'pieces of information', 'items of furniture'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-60'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 60</span>\n                <span class='rule-name'>Nouns Existing Exclusively in Plural Form</span>\n            </div>\n            <div class='rule-concept'>Tools and clothes with two symmetrical halves (scissors, tongs, spectacles, trousers, pants, jeans, pliers, binoculars) and certain entities (premises, assets, credentials, alms) are always plural and require plural verbs.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Plural-only Noun + Plural Verb | A pair of + Plural-only Noun + Singular Verb</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; My spectacles is missing from the table.</s></div><div class='eg eg-right'>&#10003; My spectacles are missing from the table.</div><div class='eg eg-right'>&#10003; A pair of spectacles was lying on the table.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> When 'a pair of' precedes the noun, the verb becomes singular.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 19, "title": "Rules 61\u201364", "html": "<div class='page-content'><div class='page-header-title'>Rules 61 to 64</div><div class='rules-container'>\n        <div class='rule-card' id='rule-61'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 61</span>\n                <span class='rule-name'>Nouns Singular in Form but Plural in Usage</span>\n            </div>\n            <div class='rule-concept'>Nouns like 'cattle', 'clergy', 'gentry', 'poultry', 'peasantry', 'folk', 'people', and 'police' look singular (no ending -s) but are treated as plurals and take plural verbs.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Cattle / Police / Clergy / People + Plural Verb</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; The cattle is grazing peacefully in the pasture.</s></div><div class='eg eg-right'>&#10003; The cattle are grazing peacefully in the pasture.</div><div class='eg eg-wrong'><s>&times; The police has registered a case.</s></div><div class='eg eg-right'>&#10003; The police have registered a case.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Never add '-s' to these nouns (e.g., 'cattles' or 'peoples' in this sense are incorrect).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-62'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 62</span>\n                <span class='rule-name'>Nouns Plural in Form but Singular in Usage</span>\n            </div>\n            <div class='rule-concept'>Nouns ending in '-s' that name academic subjects (mathematics, physics, economics, politics), illnesses (measles, mumps, rickets), games (billiards, darts), and words like 'news' and 'innings' take singular verbs.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Subject Name / Disease / News + Singular Verb</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; Mathematics is considered a scoring subject.</div><div class='eg eg-right'>&#10003; This news was broadcast yesterday.</div><div class='eg eg-note'>&bull; Note: His mathematics are weak. (Plural when meaning calculations or skills)</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> When accompanied by a possessive adjective (his, my), subject names refer to skills and take plural verbs.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-63'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 63</span>\n                <span class='rule-name'>Compound Hyphenated Modifiers Remain Singular</span>\n            </div>\n            <div class='rule-concept'>When a number and a noun combine to function as an adjective modifying a following noun, the modifying noun must always remain in its singular form.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Number + Hyphenated Singular Noun + Head Noun</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; We stayed at a five-stars luxury resort.</s></div><div class='eg eg-right'>&#10003; We stayed at a five-star luxury resort.</div><div class='eg eg-wrong'><s>&times; He handed me a ten-rupees banknote.</s></div><div class='eg eg-right'>&#10003; He handed me a ten-rupee banknote.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Only the final head noun can be pluralized (*He stayed for five days at a five-star hotel*).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-64'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 64</span>\n                <span class='rule-name'>Pluralizing Compound Nouns on the Root Word</span>\n            </div>\n            <div class='rule-concept'>When converting compound nouns into the plural form, add the plural suffix '-s' to the primary/root noun, not to the preposition or adjunct.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Root Noun (+ s) + Preposition / Adjunct</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He has two brother-in-laws.</s></div><div class='eg eg-right'>&#10003; He has two brothers-in-law.</div><div class='eg eg-wrong'><s>&times; Many passer-bys witnessed the accident.</s></div><div class='eg eg-right'>&#10003; Many passers-by witnessed the accident.</div><div class='eg eg-right'>&#10003; Commanders-in-chief, Lookers-on, Mothers-in-law.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Do not attach the plural '-s' to 'law' or 'by'.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 20, "title": "Rules 65\u201368", "html": "<div class='page-content'><div class='page-header-title'>Rules 65 to 68</div><div class='rules-container'>\n        <div class='rule-card' id='rule-65'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 65</span>\n                <span class='rule-name'>Apostrophe ('s) Rules: Inanimate Objects and Joint Ownership</span>\n            </div>\n            <div class='rule-concept'>Do not use apostrophe ('s) on non-living objects; use the preposition 'of'. In joint possession, place the apostrophe on the final noun; in separate possession, place it on each noun. Avoid double apostrophes.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Living Entity's | Leg of the table (NOT table's leg) | A and B's (joint) vs. A's and B's (separate)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; The table's surface was polished.</s></div><div class='eg eg-right'>&#10003; The surface of the table was polished.</div><div class='eg eg-right'>&#10003; Amit and Priya's joint account was opened.</div><div class='eg eg-wrong'><s>&times; My brother's friend's sister arrived.</s></div><div class='eg eg-right'>&#10003; The sister of my brother's friend arrived.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Time, weight, space, and personified objects can take apostrophes (*a day's leave, nature's fury*).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-66'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 66</span>\n                <span class='rule-name'>Omission of Articles with Meals, Languages, and Institutions</span>\n            </div>\n            <div class='rule-concept'>Do not use 'the' before meals (breakfast, lunch, dinner), languages, or institutions (school, college, church, hospital, prison) when visited for their primary, standard purpose.</div>\n            <div class='rule-formula'><strong>Formula:</strong> No 'the' for Primary Purpose | Use 'the' for Secondary / Specific Purpose</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; He goes to school every morning. (As a student)</div><div class='eg eg-right'>&#10003; His father went to the school to meet the principal. (Secondary Purpose)</div><div class='eg eg-right'>&#10003; Dinner was served at 9 PM. (General meal)</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'The French' means the French people; 'French' means the language.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-67'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 67</span>\n                <span class='rule-name'>Repetition of Articles Determines Subject Count</span>\n            </div>\n            <div class='rule-concept'>When two singular nouns are joined by 'and', placing an article before only the first noun indicates that one person holds both roles (singular verb). Placing an article before both nouns indicates two distinct individuals (plural verb).</div>\n            <div class='rule-formula'><strong>Formula:</strong> The + Noun 1 + and + Noun 2 -> Singular Verb | The + Noun 1 + and + the + Noun 2 -> Plural Verb</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; The secretary and treasurer has submitted the annual report. (One person)</div><div class='eg eg-right'>&#10003; The secretary and the treasurer have submitted the annual report. (Two persons)</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Count the articles to determine whether the subject is singular or plural.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-68'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 68</span>\n                <span class='rule-name'>Formulation of Question Tags</span>\n            </div>\n            <div class='rule-concept'>A positive statement takes a negative tag; a negative statement takes a positive tag. Pronouns like 'hardly' and 'seldom' make a sentence negative, requiring a positive tag. 'I am' takes 'aren't I?'. Imperatives with 'Let us' take 'shall we?'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Positive Statement -> Negative Tag | Negative Statement -> Positive Tag | I am -> aren't I?</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; You are ready for the test, aren't you?</div><div class='eg eg-right'>&#10003; He seldom visits us, does he?</div><div class='eg eg-right'>&#10003; I am invited to the gathering, aren't I?</div><div class='eg eg-right'>&#10003; Let's begin the review, shall we?</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Amn't I' is ungrammatical; always use 'aren't I?' in negative tags for 'I am'.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 21, "title": "Rules 69\u201372", "html": "<div class='page-content'><div class='page-header-title'>Rules 69 to 72</div><div class='rules-container'>\n        <div class='rule-card' id='rule-69'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 69</span>\n                <span class='rule-name'>Superfluous and Redundant Expressions</span>\n            </div>\n            <div class='rule-concept'>Eliminate redundant pairs where words repeat the same meaning: 'return back', 'revert back', 'repeat again', 'cousin brother/sister', 'consensus of opinion', 'equally as good as'. Also, 'the reason why' must be followed by 'that', not 'because'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Return (NOT return back) | The reason why ... that (NOT because)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; The reason why he missed the train was because of the traffic jam.</s></div><div class='eg eg-right'>&#10003; The reason why he missed the train was that there was a traffic jam.</div><div class='eg eg-wrong'><s>&times; She introduced me to her cousin brother.</s></div><div class='eg eg-right'>&#10003; She introduced me to her cousin.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Because' after 'the reason why' is one of the most frequently tested errors.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-70'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 70</span>\n                <span class='rule-name'>'Too... to' vs. 'So... that'</span>\n            </div>\n            <div class='rule-concept'>'Too... to' expresses an excessive degree with an implied negative consequence ('more than is acceptable'). Do not use 'too' to simply mean 'very' or 'extremely' in positive contexts.</div>\n            <div class='rule-formula'><strong>Formula:</strong> too + Adjective + to + V1 = so + Adjective + that + cannot + V1</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; He is too exhausted to continue working.</div><div class='eg eg-wrong'><s>&times; She is too beautiful.</s></div><div class='eg eg-right'>&#10003; She is very beautiful.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Too' carries a negative connotation unless paired in an idiomatic structure.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-71'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 71</span>\n                <span class='rule-name'>Word Order and Degree with 'Enough'</span>\n            </div>\n            <div class='rule-concept'>'Enough' as an adverb follows the adjective/adverb it modifies, and that adjective must be in the Positive Degree. As an adjective, 'enough' precedes the noun.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Positive Degree Adjective + enough | enough + Noun</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He is more intelligent enough to solve this puzzle.</s></div><div class='eg eg-right'>&#10003; He is intelligent enough to solve this puzzle.</div><div class='eg eg-right'>&#10003; We have enough provisions for the journey.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Never place 'enough' before the adjective (*'enough smart' is wrong; say 'smart enough'*).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-72'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 72</span>\n                <span class='rule-name'>'As... as' (Equative) vs. 'So... as' (Negative Only)</span>\n            </div>\n            <div class='rule-concept'>'As... as' can be used in both affirmative and negative sentences to compare identical degrees. 'So... as' is strictly restricted to negative sentences.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Affirmative & Negative: as + Positive Degree + as | Negative ONLY: not so + Positive Degree + as</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; Varun is as fast as Rohit.</div><div class='eg eg-right'>&#10003; Varun is not as fast as Rohit.</div><div class='eg eg-right'>&#10003; Varun is not so fast as Rohit.</div><div class='eg eg-wrong'><s>&times; Varun is so fast as Rohit. (Affirmative is ungrammatical)</s></div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Never use 'so... as' in an affirmative sentence.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 22, "title": "Rules 73\u201376", "html": "<div class='page-content'><div class='page-header-title'>Rules 73 to 76</div><div class='rules-container'>\n        <div class='rule-card' id='rule-73'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 73</span>\n                <span class='rule-name'>'Such... as' (Comparison/Category) vs. 'Such... that' (Result)</span>\n            </div>\n            <div class='rule-concept'>'Such... as' denotes category, comparison, or giving illustrative examples. 'Such... that' expresses a direct cause-and-effect relationship.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Such + Noun + as (Examples/Comparison) | Such + Noun + that (Result/Consequence)</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; He achieved such outstanding results as were expected of him.</div><div class='eg eg-right'>&#10003; It was such a severe storm that trees were uprooted across the city.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Check whether the clause introduces examples/nature (as) or an outcome (that).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-74'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 74</span>\n                <span class='rule-name'>'Between... and' vs. 'From... to'</span>\n            </div>\n            <div class='rule-concept'>The correlative pair for 'between' is 'and'. The correlative pair for 'from' is 'to'. You must never mix these conjunctions.</div>\n            <div class='rule-formula'><strong>Formula:</strong> between A and B | from A to B</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; The doctor will be available between 10 AM to 1 PM.</s></div><div class='eg eg-right'>&#10003; The doctor will be available between 10 AM and 1 PM.</div><div class='eg eg-right'>&#10003; The doctor will be available from 10 AM to 1 PM.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Between... to' is an extremely common colloquial error tested in banking exams.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-75'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 75</span>\n                <span class='rule-name'>Exact Placement of 'Only'</span>\n            </div>\n            <div class='rule-concept'>The adverb 'only' must immediately precede the exact word or phrase that it qualifies. Changing its position changes the grammatical subject or object being restricted.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Place 'only' directly before the restricted element</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; Only she gave me five thousand rupees. (Nobody else gave money)</div><div class='eg eg-right'>&#10003; She only lent me five thousand rupees. (She didn't gift it)</div><div class='eg eg-right'>&#10003; She gave me only five thousand rupees. (No more than this amount)</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Look at the context of the sentence to see what is genuinely being restricted.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-76'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 76</span>\n                <span class='rule-name'>Fixed Pairs: 'Seldom or never' and 'Seldom if ever'</span>\n            </div>\n            <div class='rule-concept'>The standard idiomatic adverbial pairs to express rarity are 'seldom or never' and 'seldom if ever'. Never mix them as 'seldom or ever' or 'seldom if never'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Seldom or never | Seldom if ever</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He seldom or ever neglects his duty.</s></div><div class='eg eg-right'>&#10003; He seldom or never neglects his duty.</div><div class='eg eg-right'>&#10003; He seldom if ever neglects his duty.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Remember: 'or' pairs with 'never'; 'if' pairs with 'ever'.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 23, "title": "Rules 77\u201380", "html": "<div class='page-content'><div class='page-header-title'>Rules 77 to 80</div><div class='rules-container'>\n        <div class='rule-card' id='rule-77'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 77</span>\n                <span class='rule-name'>Fixed Pairs: 'Little or nothing' and 'Little if anything'</span>\n            </div>\n            <div class='rule-concept'>Analogous to Rule 76, expressions of minimal quantity are strictly paired as 'little or nothing' and 'little if anything'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Little or nothing | Little if anything</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; There is little or anything left to salvage.</s></div><div class='eg eg-right'>&#10003; There is little or nothing left to salvage.</div><div class='eg eg-right'>&#10003; There is little if anything left to salvage.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Watch for mixed phrases like 'little if nothing' or 'little or anything'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-78'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 78</span>\n                <span class='rule-name'>Inversion with Locational and Directional Adverbs</span>\n            </div>\n            <div class='rule-concept'>When an adverb of place or direction introduces a sentence, the verb precedes the noun subject. If the subject is a personal pronoun, normal word order is maintained.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Adverbial of Place + Verb + Noun Subject | Adverbial + Pronoun + Verb</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; On top of the hill lived an old recluse.</div><div class='eg eg-right'>&#10003; Out rushed the angry crowd.</div><div class='eg eg-right'>&#10003; Here he comes. (Pronoun subject -> no inversion)</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Do not invert when the subject is a personal pronoun (he, she, they).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-79'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 79</span>\n                <span class='rule-name'>Placement of Adverbs of Frequency</span>\n            </div>\n            <div class='rule-concept'>Adverbs of indefinite frequency (always, often, rarely, seldom, never, usually) are placed before the main verb, but after auxiliary/linking verbs (is, are, was, were, have, has).</div>\n            <div class='rule-formula'><strong>Formula:</strong> Subject + [Adverb of Frequency] + Main Verb | Subject + Auxiliary Verb + [Adverb of Frequency] + Main Verb</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He speaks always the truth.</s></div><div class='eg eg-right'>&#10003; He always speaks the truth.</div><div class='eg eg-right'>&#10003; He is always punctual.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Place the adverb between the auxiliary verb and the main verb (*'He has always supported us'*).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-80'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 80</span>\n                <span class='rule-name'>Correlative Conjunctions and Parallel Parts of Speech</span>\n            </div>\n            <div class='rule-concept'>Correlative pairs (not only... but also, either... or, neither... nor) must connect words of the identical grammatical category. If 'but also' precedes a noun, 'not only' must precede a noun.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Verb + not only + Noun 1 + but also + Noun 2</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He not only visited London but also Paris.</s></div><div class='eg eg-right'>&#10003; He visited not only London but also Paris.</div><div class='eg eg-wrong'><s>&times; She either wants tea or coffee.</s></div><div class='eg eg-right'>&#10003; She wants either tea or coffee.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Identify where the second conjunction sits, and adjust the first conjunction to match.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 24, "title": "Rules 81\u201384", "html": "<div class='page-content'><div class='page-header-title'>Rules 81 to 84</div><div class='rules-container'>\n        <div class='rule-card' id='rule-81'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 81</span>\n                <span class='rule-name'>'As well as' Agreement and Pronoun Reference</span>\n            </div>\n            <div class='rule-concept'>When subjects are joined by 'as well as', verbs and possessive pronouns agree strictly with the first subject, ignoring any intervening nouns.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Subject 1 + as well as + Subject 2 + Verb (agrees with S1) + Possessive (agrees with S1)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; The principal as well as the teachers were present in their uniforms.</s></div><div class='eg eg-right'>&#10003; The principal as well as the teachers was present in his uniform.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Both the finite verb and the possessive pronoun must match the first subject.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-82'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 82</span>\n                <span class='rule-name'>'Though / Although' Takes 'Yet' or a Comma (Never 'But')</span>\n            </div>\n            <div class='rule-concept'>'Though' and 'Although' introduce concessive subordinate clauses. They can be answered by 'yet' or a comma in the main clause, but never by 'but'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Although + Clause 1, yet / [comma] + Clause 2</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Though he is poor, but he is dignified.</s></div><div class='eg eg-right'>&#10003; Though he is poor, yet he is dignified.</div><div class='eg eg-right'>&#10003; Though he is poor, he is dignified.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> The conjunction 'but' creates a coordinating conflict with 'though'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-83'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 83</span>\n                <span class='rule-name'>No 'Therefore / So' After 'Because / Since / As'</span>\n            </div>\n            <div class='rule-concept'>Do not combine causal conjunctions (because, since, as) with consecutive conjunctions (therefore, so, thus) in the same sentence.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Because / Since / As + Clause 1, Clause 2 (NO therefore / so)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Since he was ill, so he did not come to class.</s></div><div class='eg eg-right'>&#10003; Since he was ill, he did not come to class.</div><div class='eg eg-right'>&#10003; He was ill, so he did not come to class.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Use only one connector to show cause and effect.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-84'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 84</span>\n                <span class='rule-name'>Modals in Purpose Clauses: 'So that' / 'In order that'</span>\n            </div>\n            <div class='rule-concept'>When expressing purpose using 'so that' or 'in order that', use 'may' if the main clause is in the present tense, and 'might' if the main clause is in the past tense.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Present Main Clause + so that + Subject + may + V1 | Past Main Clause + so that + Subject + might + V1</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; He studies day and night so that he may crack the examination.</div><div class='eg eg-right'>&#10003; He studied day and night so that he might crack the examination.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Do not use 'will' or 'would' in purpose clauses introduced by 'so that'.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 25, "title": "Rules 85\u201388", "html": "<div class='page-content'><div class='page-header-title'>Rules 85 to 88</div><div class='rules-container'>\n        <div class='rule-card' id='rule-85'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 85</span>\n                <span class='rule-name'>'Lest... should' and Negative Restriction</span>\n            </div>\n            <div class='rule-concept'>'Lest' inherently means 'for fear that' and must strictly be followed by 'should' (or a bare subjunctive verb). It can never be accompanied by 'not'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Lest + Subject + should + V1 (no 'not', no 'will')</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Hold my hand lest you will fall.</s></div><div class='eg eg-wrong'><s>&times; Hold my hand lest you should not fall.</s></div><div class='eg eg-right'>&#10003; Hold my hand lest you should fall.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Always eliminate 'not' from the clause containing 'lest'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-86'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 86</span>\n                <span class='rule-name'>'Unless' vs. 'Until' and Subordinate Clause Constraints</span>\n            </div>\n            <div class='rule-concept'>'Unless' expresses a condition ('if not'). 'Until' expresses a time limit ('up to the time that'). Both are intrinsically negative words; never use 'not' or future modals (will, shall) inside their subordinate clauses.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Unless / Until + Affirmative Present Clause (NO not / will)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Unless you do not give your best, you will not win.</s></div><div class='eg eg-right'>&#10003; Unless you give your best, you will not win.</div><div class='eg eg-wrong'><s>&times; Wait until the manager will not arrive.</s></div><div class='eg eg-right'>&#10003; Wait until the manager arrives.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Always remove double negatives from 'unless' or 'until' clauses.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-87'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 87</span>\n                <span class='rule-name'>'In case' vs. 'If'</span>\n            </div>\n            <div class='rule-concept'>'In case' indicates advance preparation for a possible future event. 'If' introduces an action that occurs only after the condition happens. Do not use 'will' or 'would' after 'in case'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> In case + Simple Present (NO will / would)</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; Take some cash in case the card machine does not work.</div><div class='eg eg-wrong'><s>&times; Take some cash in case the card machine will not work.</s></div><div class='eg eg-right'>&#10003; Pay by cash if the card machine does not work.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'In case' is about preparedness before the event occurs.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-88'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 88</span>\n                <span class='rule-name'>Redundancy of 'Supposing if'</span>\n            </div>\n            <div class='rule-concept'>'Supposing' and 'if' both introduce hypothetical conditions. Using both together is redundant and ungrammatical. Use either 'supposing' or 'if', never both.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Use 'Supposing' OR 'If' (NEVER 'Supposing if')</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Supposing if he fails to submit the report on time, what next?</s></div><div class='eg eg-right'>&#10003; Supposing he fails to submit the report on time, what next?</div><div class='eg eg-right'>&#10003; If he fails to submit the report on time, what next?</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> In sentence correction, eliminate either 'supposing' or 'if'.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 26, "title": "Rules 89\u201392", "html": "<div class='page-content'><div class='page-header-title'>Rules 89 to 92</div><div class='rules-container'>\n        <div class='rule-card' id='rule-89'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 89</span>\n                <span class='rule-name'>Terminal Prepositions with Infinitives Modifying Nouns</span>\n            </div>\n            <div class='rule-concept'>When a noun is qualified by an infinitive (to + V1), and the noun is the instrument, location, or recipient of that verbal action, the required preposition must not be omitted at the end.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Noun + to + V1 + Required Preposition</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He has no house to live.</s></div><div class='eg eg-right'>&#10003; He has no house to live in.</div><div class='eg eg-wrong'><s>&times; Please give me a paper to write.</s></div><div class='eg eg-right'>&#10003; Please give me a paper to write on.</div><div class='eg eg-wrong'><s>&times; She needs a chair to sit.</s></div><div class='eg eg-right'>&#10003; She needs a chair to sit on.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Test whether the preposition is needed by reversing: 'to write with a pen', 'to live in a house'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-90'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 90</span>\n                <span class='rule-name'>'Agree with' vs. 'Agree to' vs. 'Agree on'</span>\n            </div>\n            <div class='rule-concept'>'Agree with' is used for a person or personal view. 'Agree to' is used for a proposal, plan, or suggestion. 'Agree on' is used for a mutual decision or topic.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Agree with + Person | Agree to + Proposal / Suggestion | Agree on + Topic / Decision</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; I agree with you completely on this issue.</div><div class='eg eg-right'>&#10003; The management agreed to the workers' proposal.</div><div class='eg eg-right'>&#10003; The delegates finally agreed on the treaty terms.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Never say 'agree to a person' or 'agree with a proposal'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-91'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 91</span>\n                <span class='rule-name'>'Angry with' vs. 'Angry at'</span>\n            </div>\n            <div class='rule-concept'>'Angry with' is used when feeling anger toward a person. 'Angry at' is used when angry at an action, behavior, or non-personal situation.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Angry with + Person | Angry at + Action / Behavior / Thing</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; The teacher was angry with the student for being late.</div><div class='eg eg-right'>&#10003; The teacher was angry at the student's continuous insolence.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Person = with; Behavior/Thing = at.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-92'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 92</span>\n                <span class='rule-name'>'Differ with' vs. 'Differ from'</span>\n            </div>\n            <div class='rule-concept'>'Differ with' means to disagree with a person in opinion. 'Differ from' means to be unlike or dissimilar in appearance, characteristics, or nature.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Differ with + Person (Opinion) | Differ from + Entity (Characteristics)</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; I differ with you regarding this economic theory.</div><div class='eg eg-right'>&#10003; This new software differs completely from its earlier version.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Differ with' is about disagreement; 'Differ from' is about dissimilarity.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 27, "title": "Rules 93\u201396", "html": "<div class='page-content'><div class='page-header-title'>Rules 93 to 96</div><div class='rules-container'>\n        <div class='rule-card' id='rule-93'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 93</span>\n                <span class='rule-name'>'Deal in' vs. 'Deal with'</span>\n            </div>\n            <div class='rule-concept'>'Deal in' means to engage in trade or commerce of a specific commodity. 'Deal with' means to manage, handle, or interact with a situation, subject, or person.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Deal in + Goods / Business | Deal with + Person / Situation / Topic</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; His firm deals in textile exports.</div><div class='eg eg-right'>&#10003; She knows how to deal with difficult clients.</div><div class='eg eg-right'>&#10003; This chapter deals with monetary policy.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Trade = in; Handling/Management = with.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-94'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 94</span>\n                <span class='rule-name'>'Blind in' vs. 'Blind to'</span>\n            </div>\n            <div class='rule-concept'>'Blind in' (or 'of') refers to physical loss of sight in an eye. 'Blind to' refers metaphorically to being oblivious or willfully ignorant of faults, reality, or danger.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Blind in + Eye (Physical) | Blind to + Faults / Realities (Metaphorical)</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; The veteran was blind in the right eye.</div><div class='eg eg-right'>&#10003; He was blind to the shortcomings of his subordinates.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Do not say 'blind of his faults'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-95'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 95</span>\n                <span class='rule-name'>'Part from' vs. 'Part with'</span>\n            </div>\n            <div class='rule-concept'>'Part from' means to take leave of or separate from a person. 'Part with' means to relinquish, give away, or sell a possession, asset, or money.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Part from + Person | Part with + Possession / Money</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; He parted from his childhood friends with a heavy heart.</div><div class='eg eg-right'>&#10003; A miser is always reluctant to part with his money.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Person = from; Belongings/Money = with.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-96'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 96</span>\n                <span class='rule-name'>'Compare with' vs. 'Compare to'</span>\n            </div>\n            <div class='rule-concept'>'Compare with' is used to contrast similar things to analyze points of resemblance and difference. 'Compare to' is used to draw a figurative or metaphorical comparison between fundamentally dissimilar things.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Compare with + Similar Entities | Compare to + Dissimilar Entities (Metaphor)</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; Kalidasa is often compared with Shakespeare. (Two dramatists)</div><div class='eg eg-right'>&#10003; The poet compared human life to a candle in the wind. (Dissimilar entities)</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Literal comparison = with; Figurative/poetic comparison = to.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 28, "title": "Rules 97\u2013100", "html": "<div class='page-content'><div class='page-header-title'>Rules 97 to 100</div><div class='rules-container'>\n        <div class='rule-card' id='rule-97'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 97</span>\n                <span class='rule-name'>'Made of' vs. 'Made from'</span>\n            </div>\n            <div class='rule-concept'>'Made of' is used when the basic raw material undergoes no chemical change and retains its physical nature. 'Made from' is used when a chemical change takes place, transforming the original material into a new substance.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Made of + Physical State Unaltered | Made from + Chemical Transformation</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; The table is made of solid oak.</div><div class='eg eg-right'>&#10003; Paper is made from wood pulp.</div><div class='eg eg-right'>&#10003; Wine is made from grapes.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> If the original material is still physically visible/unchanged, use 'made of'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-98'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 98</span>\n                <span class='rule-name'>Verbs That Forbid Prepositions Before Direct Objects</span>\n            </div>\n            <div class='rule-concept'>Transitive verbs like 'attack', 'accompany', 'comprise', 'discuss', 'describe', 'enter', 'order', 'reach', and 'resemble' take a direct object without any preposition.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Subject + [resemble / discuss / order / etc.] + Direct Object (NO preposition)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; The army attacked on the rebel outpost.</s></div><div class='eg eg-right'>&#10003; The army attacked the rebel outpost.</div><div class='eg eg-wrong'><s>&times; The daughter resembles to her mother.</s></div><div class='eg eg-right'>&#10003; The daughter resembles her mother.</div><div class='eg eg-wrong'><s>&times; We reached at the airport on time.</s></div><div class='eg eg-right'>&#10003; We reached the airport on time.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Never place 'on' after 'attack', 'about' after 'discuss', or 'to' after 'resemble'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-99'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 99</span>\n                <span class='rule-name'>'Wait for' vs. 'Await'</span>\n            </div>\n            <div class='rule-concept'>'Await' is a transitive verb that means 'wait for'. It takes a direct object and must never be followed by the preposition 'for'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> wait + for = await + Direct Object (NO 'for')</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; We are awaiting for the final test results.</s></div><div class='eg eg-right'>&#10003; We are awaiting the final test results.</div><div class='eg eg-right'>&#10003; We are waiting for the final test results.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Awaiting for' is a redundant error frequently tested in spot-the-error sections.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-100'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 100</span>\n                <span class='rule-name'>'Comprise' vs. 'Consist of'</span>\n            </div>\n            <div class='rule-concept'>In the active voice, 'comprise' means 'consist of' and takes no preposition. Never use 'comprise of' in active voice. In passive voice, 'is comprised of' is acceptable.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Active: comprise + Direct Object | Passive: is comprised of | consist + of</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; The council comprises of ten distinguished scholars.</s></div><div class='eg eg-right'>&#10003; The council comprises ten distinguished scholars.</div><div class='eg eg-right'>&#10003; The council consists of ten distinguished scholars.</div><div class='eg eg-right'>&#10003; The council is comprised of ten distinguished scholars. (Passive)</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Always remove 'of' from 'comprises' in active sentences.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 29, "title": "Rules 101\u2013104", "html": "<div class='page-content'><div class='page-header-title'>Rules 101 to 104</div><div class='rules-container'>\n        <div class='rule-card' id='rule-101'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 101</span>\n                <span class='rule-name'>'Despite' vs. 'In spite of'</span>\n            </div>\n            <div class='rule-concept'>'Despite' is a preposition meaning 'in spite of'. It must never be followed by the preposition 'of'. 'In spite' must always be followed by 'of'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Despite (NO 'of') | In spite + of</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Despite of his severe illness, he wrote the exam.</s></div><div class='eg eg-right'>&#10003; Despite his severe illness, he wrote the exam.</div><div class='eg eg-right'>&#10003; In spite of his severe illness, he wrote the exam.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Despite of' is one of the most common exam traps; cross out 'of' immediately.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-102'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 102</span>\n                <span class='rule-name'>'Enter' vs. 'Enter into'</span>\n            </div>\n            <div class='rule-concept'>When referring to physical movement into a room, building, or place, 'enter' takes no preposition. Use 'enter into' only in figurative contexts like signing an agreement, pact, treaty, or alliance.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Enter + Physical Location (NO 'into') | Enter into + Agreement / Discussion / Treaty</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; The judge entered into the courtroom.</s></div><div class='eg eg-right'>&#10003; The judge entered the courtroom.</div><div class='eg eg-right'>&#10003; India and the UK entered into a bilateral trade agreement.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Physical entry = no preposition; Metaphorical partnership/agreement = 'into'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-103'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 103</span>\n                <span class='rule-name'>Adjectives and Adverbs with Identical Forms</span>\n            </div>\n            <div class='rule-concept'>Certain words have identical forms for both adjectives and adverbs: 'fast', 'hard', 'late', 'early', 'straight'. Note that 'fastly' does not exist in English. 'Hard' (with effort) differs in meaning from 'hardly' (scarcely).</div>\n            <div class='rule-formula'><strong>Formula:</strong> He is a fast runner (Adj) | He runs fast (Adv, NOT fastly)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He drove fastly to catch the train.</s></div><div class='eg eg-right'>&#10003; He drove fast to catch the train.</div><div class='eg eg-right'>&#10003; He worked hard all his life.</div><div class='eg eg-right'>&#10003; He hardly worked today. (Scarcely worked)</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Never use 'fastly'. Distinguish 'hard' (vigorous effort) from 'hardly' (scarcely/barely).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-104'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 104</span>\n                <span class='rule-name'>Position of Adverb of Manner Relative to Direct Objects</span>\n            </div>\n            <div class='rule-concept'>An adverb of manner must never be placed between a transitive verb and its direct object. Place it either after the object or before the verb.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Subject + Verb + Direct Object + Adverb of Manner</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He explained clearly the complex theorem.</s></div><div class='eg eg-right'>&#10003; He explained the complex theorem clearly.</div><div class='eg eg-right'>&#10003; She sang the national anthem melodiously.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Never separate a transitive verb from its object with an adverb.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 30, "title": "Rules 105\u2013108", "html": "<div class='page-content'><div class='page-header-title'>Rules 105 to 108</div><div class='rules-container'>\n        <div class='rule-card' id='rule-105'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 105</span>\n                <span class='rule-name'>Order of Multiple Adverbs: The M-P-T Rule</span>\n            </div>\n            <div class='rule-concept'>When adverbs of Manner (M), Place (P), and Time (T) qualify the same verb in a sentence, they must be arranged in the sequence: Manner -> Place -> Time.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Subject + Verb + [Manner] + [Place] + [Time]</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He performed yesterday brilliantly at the auditorium.</s></div><div class='eg eg-right'>&#10003; He performed brilliantly (M) at the auditorium (P) yesterday (T).</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Remember the acronym M-P-T (Manner, Place, Time).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-106'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 106</span>\n                <span class='rule-name'>'Very' vs. 'Much' Usage Nuances</span>\n            </div>\n            <div class='rule-concept'>'Very' modifies adjectives and adverbs in the Positive Degree and Present Participles (V1+ing). 'Much' modifies Comparative Degree adjectives and Past Participles (V3).</div>\n            <div class='rule-formula'><strong>Formula:</strong> Very + Positive Degree / V1+ing | Much + Comparative Degree / V3</div>\n            <div class='rule-examples'><div class='eg eg-right'>&#10003; This is a very interesting novel.</div><div class='eg eg-right'>&#10003; He was much annoyed by their reckless behavior.</div><div class='eg eg-right'>&#10003; This version is much better than the previous one.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Use 'much' with comparative adjectives (*'much stronger'*, not *'very stronger'*).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-107'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 107</span>\n                <span class='rule-name'>'Between' Cannot Directly Precede 'Each'</span>\n            </div>\n            <div class='rule-concept'>'Between' requires two distinct reference points. Saying 'between each' is ungrammatical. Use 'between... and', 'between [plural noun]', or 'after each'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> between + Plural Noun (NOT between each + Singular Noun)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; There should be a pause of five minutes between each round.</s></div><div class='eg eg-right'>&#10003; There should be a pause of five minutes between rounds.</div><div class='eg eg-right'>&#10003; There should be a pause of five minutes after each round.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Between each student' is incorrect; say 'between every two students' or 'between students'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-108'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 108</span>\n                <span class='rule-name'>Expressing Plural Quantity of Uncountable Nouns</span>\n            </div>\n            <div class='rule-concept'>Uncountable nouns (advice, information, furniture, bread, jewelry) cannot take an '-s'. To indicate plurality or specific quantity, precede them with count nouns like 'pieces of', 'items of', 'loaves of', or 'sheets of'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Number / Quantifier + [pieces / items / loaves] + of + Uncountable Noun</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He ordered three furnitures for the new office.</s></div><div class='eg eg-right'>&#10003; He ordered three items of furniture for the new office.</div><div class='eg eg-right'>&#10003; He bought two loaves of bread.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Do not pluralize the uncountable noun itself (*'pieces of advices' is wrong; say 'pieces of advice'*).</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 31, "title": "Rules 109\u2013112", "html": "<div class='page-content'><div class='page-header-title'>Rules 109 to 112</div><div class='rules-container'>\n        <div class='rule-card' id='rule-109'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 109</span>\n                <span class='rule-name'>Correcting Erroneous Common Collocations</span>\n            </div>\n            <div class='rule-concept'>Certain common colloquial phrases are grammatically incorrect in standard English: 'English teacher' strictly means a teacher of English nationality; use 'the teacher of English'. Avoid 'family members'; use 'members of the family'. Use 'pass marks' (not 'passing marks').</div>\n            <div class='rule-formula'><strong>Formula:</strong> Teacher of English (Subject) | Members of the family | Pass marks</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He is our new English teacher. (Unless referring to nationality)</s></div><div class='eg eg-right'>&#10003; He is our new teacher of English.</div><div class='eg eg-wrong'><s>&times; All his family members were present.</s></div><div class='eg eg-right'>&#10003; All the members of his family were present.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Passing marks' is colloquial; formal examinations strictly test 'pass marks'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-110'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 110</span>\n                <span class='rule-name'>Definite Article 'The' with Body Parts in Prepositional Phrases</span>\n            </div>\n            <div class='rule-concept'>When an action is performed upon a part of a person's body and the person is already identified as the object of the verb, use the definite article 'the' instead of a possessive adjective before the body part.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Verb + Object + Preposition + the + Body Part (NOT possessive adjective)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; The brick hit him on his head.</s></div><div class='eg eg-right'>&#10003; The brick hit him on the head.</div><div class='eg eg-wrong'><s>&times; She held the child by his arm.</s></div><div class='eg eg-right'>&#10003; She held the child by the arm.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Do not repeat the possessive pronoun (*his head, her arm*) when the person is already the verb object.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-111'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 111</span>\n                <span class='rule-name'>'Fewer' vs. 'Less' Distinctions and Exceptions</span>\n            </div>\n            <div class='rule-concept'>'Fewer' is used with plural countable nouns. 'Less' is used with singular uncountable nouns. Exception: When periods of time, distances, or sums of money are considered as a single collective amount, use 'less'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Fewer + Plural Countable Noun | Less + Uncountable Noun / Unified Unit of Time & Money</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; There were less participants than expected.</s></div><div class='eg eg-right'>&#10003; There were fewer participants than expected.</div><div class='eg eg-right'>&#10003; The applicant has less experience than required.</div><div class='eg eg-right'>&#10003; The flight was completed in less than three hours. (Single unit of time)</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Countable items take 'fewer', but singular amounts/durations take 'less'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-112'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 112</span>\n                <span class='rule-name'>'Elder' / 'Eldest' vs. 'Older' / 'Oldest' Constraints</span>\n            </div>\n            <div class='rule-concept'>'Elder' and 'eldest' are restricted exclusively to members of the same family (blood relations) and are never followed by 'than'. 'Older' and 'oldest' apply to people outside the family and inanimate objects, and are followed by 'than'.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Elder (blood relative, NO 'than') | Older than (comparative for general age)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; He is elder than his batchmate.</s></div><div class='eg eg-right'>&#10003; He is older than his batchmate.</div><div class='eg eg-right'>&#10003; She is my elder sister.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Elder' never takes 'than'. If you see 'than', the word must be 'older'.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 32, "title": "Rules 113\u2013116", "html": "<div class='page-content'><div class='page-header-title'>Rules 113 to 116</div><div class='rules-container'>\n        <div class='rule-card' id='rule-113'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 113</span>\n                <span class='rule-name'>The 'Other' Rule in Comparative Exclusions</span>\n            </div>\n            <div class='rule-concept'>When comparing an individual person or item with other members of the same class or category in the comparative degree, use 'any other' to exclude the subject from itself. Omit 'other' if comparing across different classes.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Same Class: Comparative + than any other + Singular Noun | Different Class: Comparative + than any + Singular Noun</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Iron is more useful than any metal. (Iron is itself a metal)</s></div><div class='eg eg-right'>&#10003; Iron is more useful than any other metal.</div><div class='eg eg-right'>&#10003; Diamond is harder than any metal. (Diamond is not a metal)</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Failing to include 'other' results in comparing an entity against itself.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-114'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 114</span>\n                <span class='rule-name'>Plural Noun and Singular Verb with Distributive Pronouns</span>\n            </div>\n            <div class='rule-concept'>Phrases like 'Each of', 'Either of', 'Neither of', 'One of', and 'Every one of' select one unit from a group. They are followed by a plural noun/pronoun, but strictly require a singular finite verb.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Each of / Either of / Neither of / One of + Plural Noun + Singular Verb</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Neither of the solutions are feasible.</s></div><div class='eg eg-right'>&#10003; Neither of the solutions is feasible.</div><div class='eg eg-wrong'><s>&times; Either of the candidates are qualified.</s></div><div class='eg eg-right'>&#10003; Either of the candidates is qualified.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> The plural noun before the verb is the object of the preposition 'of', not the subject.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-115'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 115</span>\n                <span class='rule-name'>Objective Case Following 'But', 'Except', and 'Between'</span>\n            </div>\n            <div class='rule-concept'>When 'but' or 'except' is used as a preposition meaning 'excluding', any following pronoun must be in the Objective Case (me, us, him, her, them). Similarly, pronouns following 'between' must be objective.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Preposition (but / except / between) + Objective Pronoun (me, him, her, them)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; Everyone passed the examination except he.</s></div><div class='eg eg-right'>&#10003; Everyone passed the examination except him.</div><div class='eg eg-wrong'><s>&times; Nobody was present in the auditorium but I.</s></div><div class='eg eg-right'>&#10003; Nobody was present in the auditorium but me.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Do not be misled into using the subjective case at the end of the sentence.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-116'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 116</span>\n                <span class='rule-name'>Pseudo-Subject 'It' with Subjective Pronouns</span>\n            </div>\n            <div class='rule-concept'>When 'It' acts as an introductory pseudo-subject followed by a form of 'be' (is, was), the complement pronoun must be in the Subjective Case, and the relative clause verb agrees with that pronoun.</div>\n            <div class='rule-formula'><strong>Formula:</strong> It is / was + Subjective Case (I, he, she, they) + who/that + Verb</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; It was him who led the expedition.</s></div><div class='eg eg-right'>&#10003; It was he who led the expedition.</div><div class='eg eg-wrong'><s>&times; It is me who has drafted the proposal.</s></div><div class='eg eg-right'>&#10003; It is I who have drafted the proposal.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'It is me' is common in casual conversation, but formal exams require 'It is I'.</div>\n        </div>\n        </div></div>"}, {"type": "rules", "page_num": 33, "title": "Rules 117\u2013120", "html": "<div class='page-content'><div class='page-header-title'>Rules 117 to 120</div><div class='rules-container'>\n        <div class='rule-card' id='rule-117'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 117</span>\n                <span class='rule-name'>Connectors with 'Such', 'Else', 'Other', and 'Otherwise'</span>\n            </div>\n            <div class='rule-concept'>'Else' is followed by 'but'. 'Other', 'otherwise', and 'rather' are followed by 'than'. 'Such' is followed by 'as' (category/example) or 'that' (result).</div>\n            <div class='rule-formula'><strong>Formula:</strong> Else ... but | Other / Otherwise / Rather ... than</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; It was nothing else than sheer negligence.</s></div><div class='eg eg-right'>&#10003; It was nothing else but sheer negligence.</div><div class='eg eg-wrong'><s>&times; He had no other choice but to resign.</s></div><div class='eg eg-right'>&#10003; He had no other choice than to resign.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> 'Else' takes 'but', never 'than'. 'Other' takes 'than', never 'but'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-118'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 118</span>\n                <span class='rule-name'>Apostrophe Rules with Plural Nouns Ending in 's'</span>\n            </div>\n            <div class='rule-concept'>For regular plural nouns ending in '-s', indicate possession by adding only an apostrophe at the end (do not add an additional 's'). For irregular plurals not ending in '-s', add apostrophe + s ('s).</div>\n            <div class='rule-formula'><strong>Formula:</strong> Regular Plural ending in -s + Apostrophe (') | Irregular Plural not ending in -s + ('s)</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; This is a boys's school.</s></div><div class='eg eg-right'>&#10003; This is a boys' school.</div><div class='eg eg-right'>&#10003; The teachers' common room was renovated.</div><div class='eg eg-right'>&#10003; Children's park, Women's hostel, Men's wear.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Never write 'girls's' or 'students's'.</div>\n        </div>\n        \n        <div class='rule-card' id='rule-119'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 119</span>\n                <span class='rule-name'>Possession with Compound Indefinite Pronouns + 'Else'</span>\n            </div>\n            <div class='rule-concept'>When indefinite pronouns (somebody, anybody, someone, anyone, nobody, everyone) are combined with 'else', place the possessive apostrophe ('s) on 'else', not on the pronoun.</div>\n            <div class='rule-formula'><strong>Formula:</strong> Indefinite Pronoun + else's</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; This notebook is somebody's else.</s></div><div class='eg eg-right'>&#10003; This notebook is somebody else's.</div><div class='eg eg-wrong'><s>&times; Do not rely on anyone's else judgment.</s></div><div class='eg eg-right'>&#10003; Do not rely on anyone else's judgment.</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> Always put the apostrophe on 'else' (*somebody else's*, never *somebody's else*).</div>\n        </div>\n        \n        <div class='rule-card' id='rule-120'>\n            <div class='rule-card-header'>\n                <span class='rule-badge'>Rule 120</span>\n                <span class='rule-name'>Predicative-Only Adjectives</span>\n            </div>\n            <div class='rule-concept'>Certain adjectives beginning with 'a-' (afraid, alike, alive, alone, ashamed, asleep, awake, aware) can only be used predicatively (after a linking verb), never attributively (directly before a noun).</div>\n            <div class='rule-formula'><strong>Formula:</strong> Subject + Linking Verb + Predicative Adjective (NO 'an afraid man' or 'an asleep child')</div>\n            <div class='rule-examples'><div class='eg eg-wrong'><s>&times; An asleep dog was lying near the doorstep.</s></div><div class='eg eg-right'>&#10003; The dog was asleep near the doorstep.</div><div class='eg eg-wrong'><s>&times; He met an afraid traveller on the road.</s></div><div class='eg eg-right'>&#10003; He met a frightened traveller on the road (or: The traveller was afraid).</div></div>\n            <div class='rule-trap'><strong>Exam Alert:</strong> If modifying a noun directly, replace predicative 'a-' adjectives with attributive equivalents (e.g., *sleeping child*, *frightened person*, *living creature*).</div>\n        </div>\n        </div></div>"}, {"type": "back_cover", "page_num": 34, "title": "Back Cover", "html": "\n    <div class=\"page-cover back-cover\">\n        <h2 class=\"back-title\">Master Grammar & Conquer Exams</h2>\n        <div class=\"back-divider\"></div>\n        <div class=\"back-text\">\n            <p>English grammar for competitive exams is not about memorizing thousands of arbitrary patterns; it is about mastering the core 120 mathematical structural formulas that recur consistently.</p>\n            <p><strong>Daily 3-Step Strategy:</strong></p>\n            <ol>\n                <li>Review the <strong>Executive Quick Recall Sheet</strong> daily.</li>\n                <li>Practice 20 error detection questions applying these exact rules.</li>\n                <li>Mark your frequent trap areas using the in-app bookmark tool.</li>\n            </ol>\n        </div>\n        <div class=\"back-stats\">\n            <div class=\"stat-box\">\n                <span class=\"stat-num\">120</span>\n                <span class=\"stat-label\">Core Rules</span>\n            </div>\n            <div class=\"stat-box\">\n                <span class=\"stat-num\">30</span>\n                <span class=\"stat-label\">Quick Triggers</span>\n            </div>\n            <div class=\"stat-box\">\n                <span class=\"stat-num\">100%</span>\n                <span class=\"stat-label\">Exam Tested</span>\n            </div>\n        </div>\n        <div class=\"back-footer\">\n            <span>Interactive 3D Flipbook Edition | PWA Offline Enabled</span>\n        </div>\n    </div>\n    "}];
